version.transform:
(
  $count($) > 1 ? $throw("Visualization recieved more than one tag value. Please check your parameters transform.");

  $value := $coalesce([value, currentValue]);
  $high := $isNilOrEmpty(minimumValue) or $isNilOrEmpty($value)
    ? false
    : $value < minimumValue;
  $low := $isNilOrEmpty(maximumValue) or $isNilOrEmpty($value)
    ? false
    : $value > maximumValue;

  $color := $high or $low
              ? "#ff0000" 
              : "#00ff00";
  {
    "chart": {
      "caption": equipment.name & " " & zone.name,
      "subcaption": $coalesce([minimumValue, ""]) & "-" & $coalesce([maximumValue, ""]),
      "captionFontSize": "18",
      "lowerlimit": minimumValue,
      "upperlimit": maximumValue,
      "valueFontSize": "24",
      "valueFontBold": "1",
      "showLimits": "1",
      /* "valuePadding": "10", */
      /* "captionPadding": "5", */
      "showTickValues": "0",
      "valueFontColor": $color,
      "numbersuffix": "°",
      "thmfillcolor": $color,
      "showgaugeborder": "1",
      "gaugebordercolor": $color,
      "gaugeborderthickness": "2",
      "plottooltext": "Temperature: <b>$datavalue</b> ",
      "theme": "fusion",
      "showvalue": "1"
    },
    "value": $value
  }
)
